import { ExecArgs } from "@medusajs/framework/types"
import { ContainerRegistrationKeys } from "@medusajs/framework/utils"

/**
 * Rewrite legacy (pre-affiliate) PrestaShop products: strip emojis, fix
 * typography, restructure description with SEO-oriented sections, rebuild
 * subtitle / meta_title / meta_description from the actual content (no
 * fabricated facts). FAQs + benefits are regenerated by enrich-legacy-products
 * which should run AFTER this one to pick up the cleaned description.
 *
 * Skips products that already carry an affiliate_source (recently imported,
 * already well structured) and casque-anti-bruit-bebe (curated separately).
 */

// Remove all emoji + symbol ranges we actually see in the DB (U+1F300..U+1FAFF,
// plus dingbats / misc symbols). Keep letters, digits, punctuation and accented
// Latin characters.
function stripEmojis(s: string): string {
  if (!s) return s
  return s
    .replace(/[\u{1F000}-\u{1FFFF}]/gu, "")
    .replace(/[\u{2600}-\u{27BF}]/gu, "")
    .replace(/[\u{FE00}-\u{FE0F}]/gu, "")
    .replace(/[\u{200D}]/gu, "")
}

function fixTypography(s: string): string {
  if (!s) return s
  return s
    .replace(/[\u2019\u2018]/g, "'")
    .replace(/[\u201C\u201D]/g, '"')
    .replace(/\u2026/g, "...")
    .replace(/\u2013/g, "-")
    .replace(/\u2014/g, " — ")
    .replace(/\r\n?/g, "\n")
    .replace(/\s+,/g, ",")
    .replace(/ {2,}/g, " ")
    // Truncated words commonly observed in the DB
    .replace(/\bfait parti des\b/gi, "fait partie des")
    .replace(/\bfait parti de\b/gi, "fait partie de")
    .replace(/\bparmi les\b/gi, "parmi les")
    .trim()
}

function stripHtml(html: string): string {
  return html
    .replace(/<img[^>]*>/gi, "")
    .replace(/<details[^>]*>[\s\S]*?<\/details>/gi, "")
    .replace(/<h2[^>]*>\s*Questions fréquentes\s*<\/h2>/gi, "")
    .replace(/<script[\s\S]*?<\/script>/gi, "")
    .replace(/<style[\s\S]*?<\/style>/gi, "")
    .replace(/<[^>]+>/g, " ")
    .replace(/&nbsp;/g, " ")
    .replace(/&amp;/g, "&")
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\s+/g, " ")
    .trim()
}

function extractSentences(text: string): string[] {
  return text
    .split(/(?<=[.!?])\s+(?=[A-ZÀ-Ü])/g)
    .map((s) => s.trim())
    .filter((s) => s.length > 10 && s.length < 400)
}

