function buildIntro(title: string, cleanText: string, ch: string): string {
  const cfg = COLLECTION_META[ch]
  if (!cfg) return ""
  // Take first 1-2 factual sentences of the original text as starting material
  const sentences = extractSentences(cleanText)
  const lead = sentences.slice(0, 2).join(" ")
  return `<p>${lead || `${title} est un ${cfg.singular} pensé pour ${cfg.useCase}.`}</p>`
}

function buildBenefitsHtml(benefits: string[]): string {
  if (benefits.length === 0) return ""
  return `<h2>Les points forts</h2>\n<ul>\n${benefits.map((b) => `  <li>${b}</li>`).join("\n")}\n</ul>`
}

function buildUseCaseHtml(ch: string, cleanText: string): string {
  const cfg = COLLECTION_META[ch]
  if (!cfg) return ""
  const sentences = extractSentences(cleanText)
  // Try to find sentences about usage / when / how
  const usage = sentences.filter((s) =>
    /utilis|appliqu|poser|port(?:ez|er)|stéril|après chaque|avant chaque|dès|pendant|entre les tétées|quand|comment/i.test(s)
  ).slice(0, 3)
  if (usage.length === 0) return ""
  return `<h2>Quand et comment l'utiliser ?</h2>\n${usage.map((s) => `<p>${s}</p>`).join("\n")}`
}

function buildSummaryHtml(ch: string, cleanText: string, title: string): string {
  const sentences = extractSentences(cleanText)
  // Keep remaining factual sentences (exclude those already used in intro + usage)
  const remaining = sentences.slice(2).filter((s) =>
    !/utilis|appliqu|poser|port(?:ez|er)|stéril|après chaque|avant chaque|dès|pendant|entre les tétées|quand|comment/i.test(s)
  ).slice(0, 5)
  if (remaining.length === 0) return ""
  return `<h2>En détail</h2>\n${remaining.map((s) => `<p>${s}</p>`).join("\n")}`
}

function buildCrossLinkHtml(ch: string): string {
  const cfg = COLLECTION_META[ch]
  if (!cfg) return ""
  const links = cfg.sisters.map((s) => `<a href="${s.href}" class="text-primary hover:underline font-medium">${s.label}</a>`).join(" ou nos ")
  return `<div class="mt-6 p-5 bg-bg-light rounded-2xl">
<p class="text-sm"><strong>Vous aimerez aussi :</strong> découvrez notre sélection de ${links}.</p>
</div>`
}

export default async function rewriteLegacyProducts({ container }: ExecArgs) {
  const logger = container.resolve(ContainerRegistrationKeys.LOGGER)
  const pg = container.resolve(ContainerRegistrationKeys.PG_CONNECTION) as any

  const res = await pg.raw(`
    SELECT p.id, p.handle, p.title, p.subtitle, p.description, p.metadata, c.handle AS collection_handle
    FROM product p
    LEFT JOIN product_collection c ON p.collection_id = c.id
    WHERE p.deleted_at IS NULL
      AND p.status = 'published'
      AND (p.metadata->>'affiliate_source') IS NULL
      AND c.handle IS NOT NULL
      AND c.handle <> 'casque-anti-bruit-bebe'
  `)

  let rewritten = 0
  let skipped = 0

  for (const row of res.rows || []) {
    const ch = row.collection_handle
    const cfg = COLLECTION_META[ch]
    if (!cfg) { skipped++; continue }

    const cleanTitle = fixTypography(stripEmojis(row.title || ""))
    const cleanSubtitle = fixTypography(stripEmojis(row.subtitle || ""))
    const rawDesc = row.description || ""
    const rawText = fixTypography(stripEmojis(stripHtml(rawDesc)))

    const existingMeta = row.metadata || {}
    const benefits: string[] = Array.isArray(existingMeta.benefits) ? existingMeta.benefits : []

    // Rebuild description from cleaned source
    const intro = buildIntro(cleanTitle, rawText, ch)
    const benefitsBlock = buildBenefitsHtml(benefits)
    const useCaseBlock = buildUseCaseHtml(ch, rawText)
    const summaryBlock = buildSummaryHtml(ch, rawText, cleanTitle)
    const crossLinkBlock = buildCrossLinkHtml(ch)

    const newDesc = [intro, benefitsBlock, useCaseBlock, summaryBlock, crossLinkBlock]
      .filter(Boolean).join("\n\n")

    // Rebuild SEO meta
    const metaTitle = (cleanTitle.length <= 55 ? cleanTitle : cleanTitle.substring(0, 52).replace(/\s+\S*$/, "")) + " | Magic Crochet Kit"
    const firstBenefit = benefits[0] || `${cfg.singular.charAt(0).toUpperCase() + cfg.singular.slice(1)} sélectionné par Magic Crochet Kit`
    const metaDesc = `${cleanTitle}. ${firstBenefit}. Livraison rapide, paiement sécurisé.`.substring(0, 160)

    // Rebuild subtitle: short factual tag
    const newSubtitle = cleanSubtitle || `${cfg.singular.charAt(0).toUpperCase() + cfg.singular.slice(1)}`

    const newMeta = {
      ...existingMeta,
      meta_title: metaTitle,
      meta_description: metaDesc,
    }

    await pg.raw(
      `UPDATE product SET title = ?, subtitle = ?, description = ?, metadata = ?::jsonb WHERE id = ?`,
      [cleanTitle, newSubtitle, newDesc, JSON.stringify(newMeta), row.id]
    )

    rewritten++
    logger.info(`  + ${row.handle}`)
  }

  logger.info(`\nDone: ${rewritten} rewritten, ${skipped} skipped`)
}
